```ts
interface Visitor {
  visitNumber(n: NumberNode): string;
  visitBinaryOp(n: BinaryOpNode): string;
}

abstract class Node { abstract accept(v: Visitor): string; }

class NumberNode extends Node {
  constructor(public value: number) { super(); }
  accept(v: Visitor) { return v.visitNumber(this); }
}
class BinaryOpNode extends Node {
  constructor(public op: string, public left: Node, public right: Node) { super(); }
  accept(v: Visitor) { return v.visitBinaryOp(this); }
}

class PrintVisitor implements Visitor {
  visitNumber(n: NumberNode) { return String(n.value); }
  visitBinaryOp(n: BinaryOpNode) {
    return `(${n.left.accept(this)} ${n.op} ${n.right.accept(this)})`;
  }
}

const tree = new BinaryOpNode('+', new NumberNode(2), new NumberNode(3));
new PrintVisitor().visitBinaryOp(tree as BinaryOpNode); // "(2 + 3)"
```

Adding `TypeCheckVisitor` later needs zero changes to `NumberNode` or `BinaryOpNode` — just a new class implementing `Visitor`.
